<?php $items = kimpu_homepage_page_children( 'kimpu_testimonials_source_page', 0 ); ?><section class="section <?php echo esc_attr( kimpu_homepage_section_classes( 'testimonials' ) ); ?>" id="testimonials"><div class="container"><?php kimpu_homepage_section_header( 'testimonials' ); ?><?php if ( $items ) : ?><div class="testimonial-grid"><?php foreach ( $items as $item ) : ?><article class="testimonial-card"><?php if ( has_post_thumbnail( $item->ID ) ) { echo get_the_post_thumbnail( $item->ID, 'thumbnail', array( 'alt' => esc_attr( get_the_title( $item->ID ) ) ) ); } ?><blockquote><?php echo wp_kses_post( wpautop( $item->post_content ) ); ?></blockquote><cite><?php echo esc_html( $item->post_title ); ?></cite></article><?php endforeach; ?></div><?php else : ?><p class="empty-state"><?php esc_html_e( 'Select a parent page with published child pages to show testimonials.', 'kimpu-multipurpose' ); ?></p><?php endif; ?></div></section>
